#!/usr/bin/env bash
#
# Clone a Hydra development checkout.
#
# Two repositories: the framework monorepo and the application skeleton. The
# sixteen hydrakit/* package repositories are generated by the split workflow
# and are not development checkouts — do not clone them to work in.
set -euo pipefail

DIR="${HYDRA_DIR:-$HOME/projects/hydra-foundation}"
mkdir -p "$DIR"

for repo in hydra app; do
    if [ -d "$DIR/$repo/.git" ]; then
        printf '%s already exists\n' "$repo"
    else
        git clone "git@github.com:hydra-foundation/$repo" "$DIR/$repo"
    fi
done

echo
echo "Next:"
echo "  cd $DIR/hydra && composer install"
echo "  cd $DIR/app  && COMPOSER=composer.dev.json composer install"
